  min-width: 0;
}

.eyebrow {
  margin-bottom: 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.title {
  margin-bottom: 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.subtitle {
  max-width: 560px;
  margin-bottom: 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.e2ee {
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin-bottom: 14px;
  padding: 6px 10px;
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.e2ee i {
  font-size: 12px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  column-gap: 10px;
  row-gap: 8px;
  margin-bottom: 14px;
}

.search {
  position: relative;
  display: flex;
  flex: 1 1 220px;
  max-width: 300px;
  align-items: center;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  outline: none;
  background: var(--bw-warm-cream);
  color: var(--bw-deep-steel);
  font-family: inherit;
  font-size: 13px;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.contact {
  display: flex;
  align-items: center;
  gap: 8px;
}

.scopeNote {
  max-width: 190px;
  color: var(--bw-text-secondary);
  font-size: 11px;
  line-height: 1.35;
}

.primaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: not-allowed;
}

.primaryBtn:disabled {
  opacity: 0.6;
}

.resultCount {
  margin-left: auto;
  color: var(--bw-steel-mist);
  font-size: 12px;
  white-space: nowrap;
}

.loading {
  padding: 12px;
  color: var(--bw-text-secondary);
  font-size: 13px;
}

.errorAlert {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 14px;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

.errorAlert i {
  margin-top: 1px;
  flex-shrink: 0;
}

.pager {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  color: var(--bw-ink-steel);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
  transition: border-color 0.12s, color 0.12s, background 0.12s;
}

.pageBtn i {
  font-size: 14px;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  cursor: default;
  opacity: 0.5;
}

.pageActive,
.pageActive:hover:not(:disabled) {
  border-color: var(--bw-deep-steel);
  background: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

