import { useEffect, useState, type FormEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount } from '../../lib/threads';
import type { ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  now?: Date | undefined;
  /** La recibe el shell desde App.tsx (cableado posterior de MSG-02).
   *  MSG-02 no existe todavía: la prop se acepta pero no se usa. */
  onOpenThread?: (threadId: string) => void;
}

const NOOP = (): void => undefined;

function errorDetail(error: unknown): string {
  if (error instanceof Error) {
    return error.message || 'Error desconocido';
  }
  if (typeof error === 'string' && error.trim() !== '') {
    return error;
  }
  if (typeof error === 'object' && error !== null) {
    const record = error as { code?: unknown; message?: unknown };
    const pieces: string[] = [];
    if (typeof record.code === 'string' && record.code.trim() !== '') {
      pieces.push(`Código ${record.code}`);
    }
    if (typeof record.message === 'string' && record.message.trim() !== '') {
      pieces.push(record.message);
    }
    if (pieces.length > 0) return pieces.join(' · ');
    try {
      const serialized = JSON.stringify(error);
      return serialized === undefined ? '' : serialized;
    } catch {
      return '';
    }
  }
  return '';
}

export function Messages({ profile, now }: MessagesProps) {
  const [draft, setDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (cancelled) return;
        setThreads(result.threads);
        setTotal(result.total);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setThreads([]);
        setTotal(0);
        setError(err);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  function handleSearchSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const next = draft.trim();
    setSearch(next);
    setPage(1);
  }

  function goToPage(next: number) {
    const maxPage = pageCount(total);
    if (next >= 1 && next <= maxPage) {
      setPage(next);
    }
  }

  const clock = now ?? new Date();
  const maxPage = pageCount(total);
  const pageNumbers = Array.from({ length: maxPage }, (_, index) => index + 1);
  const detail = errorDetail(error);

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      <div className={styles.e2ee}>
        <i className="ti ti-lock" aria-hidden="true" />
        <span>E2EE activo · claves de sesión en memoria · descifrado local</span>
      </div>

      <div className={styles.actions}>
        <form className={styles.search} onSubmit={handleSearchSubmit}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="search"
            className={styles.searchInput}
            value={draft}
            onChange={(event) => {
              setDraft(event.target.value);
              if (page !== 1) setPage(1);
            }}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
          />
        </form>

        <div className={styles.contact}>
          <button type="button" className={styles.primaryBtn} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.scopeNote} data-testid="directorio-scope">
            El Directorio (DIR-01) queda fuera del MVP
          </span>
        </div>

        <span className={styles.resultCount} data-testid="pag-info">
          {`${total} hilos · Página ${page} de ${maxPage}`}
        </span>
      </div>

      {loading ? (
        <div className={styles.loading} role="status">
          Cargando hilos…
        </div>
      ) : error ? (
        <div className={styles.errorAlert} role="alert">
          <i className="ti ti-alert-circle" aria-hidden="true" />
          <span>
            No se pudieron cargar los hilos.{detail ? ` ${detail}` : ''}
          </span>
        </div>
      ) : (
        <ThreadList threads={threads} now={clock} onOpen={NOOP} />
      )}

      <div className={styles.pager}>
        <button
          type="button"
          className={styles.pageBtn}
          onClick={() => goToPage(page - 1)}
          disabled={page <= 1}
          aria-label="Página anterior"
        >
          <i className="ti ti-chevron-left" aria-hidden="true" />
        </button>
        {pageNumbers.map((number) => (
          <button
            key={number}
            type="button"
            className={`${styles.pageBtn} ${number === page ? styles.pageActive : ''}`}
            onClick={() => goToPage(number)}
            aria-current={number === page ? 'page' : undefined}
            aria-label={`Página ${number}`}
          >
            {number}
          </button>
        ))}
        <button
          type="button"
          className={styles.pageBtn}
          onClick={() => goToPage(page + 1)}
          disabled={page >= maxPage}
          aria-label="Página siguiente"
        >
          <i className="ti ti-chevron-right" aria-hidden="true" />
        </button>
      </div>
    </div>
  );
}

