import { previewLabel, relativeTime, stateTone } from '../../lib/threads';
import type { StateTone, ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: 'abierto',
  info: 'consulta',
  warn: 'oferta',
  success: 'acuerdo',
  closed: 'cerrado',
};

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para
          contactar con otras organizaciones.
        </p>
        <div className={styles.emptyAction}>
          <button type="button" className={styles.emptyBtn} disabled>
            Ir al Directorio
          </button>
          <span className={styles.emptyScope}>
            El Directorio (DIR-01) queda fuera del MVP
          </span>
        </div>
      </div>
    );
  }

  const clock = now ?? new Date();

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        const badgeClass = toneClass
          ? `${styles.stateBadge} ${styles[toneClass] ?? ''}`
          : styles.stateBadge;

        return (
          <li key={thread.id} className={styles.listRow}>
            <button
              type="button"
              className={styles.rowButton}
              aria-label={`Abrir hilo con ${thread.counterpartyName}`}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowHeader}>
                <span className={styles.orgName}>{thread.counterpartyName}</span>
                <span className={styles.countryBadge}>
                  {thread.counterpartyCountry}
                </span>
                <span className={styles.timestamp}>
                  {relativeTime(thread.lastItemAt, clock)}
                </span>
              </span>
              <span className={styles.rowMeta}>
                <span className={styles.preview}>
                  {previewLabel(thread.lastItem)}
                </span>
                <span className={badgeClass}>{thread.state}</span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
